L(OA, 7,
  "Aprenderé a revisar todo lo aprendido y a aplicarlo en un texto nuevo: tesis, evidencia, hechos y opiniones, recursos, contexto y postura propia.",
  ["Reconozco tesis y argumentos.", "Evalúo pertinencia, suficiencia y contexto.", "Formulo mi postura con razones."],
  ["Evaluar un texto argumentativo combina varios pasos. Primero se identifica la tesis y se separan hechos de opiniones. Luego se revisa si la evidencia es pertinente y suficiente. Después se observan la organización del texto y los recursos, como las preguntas retóricas, y se sitúa el texto en su contexto. Al final se declara una postura propia con razones.",
   "Una forma práctica de revisar es usar una lista: ¿Cuál es la tesis? ¿Qué hechos la sostienen? ¿Qué opiniones hay? ¿La evidencia es pertinente y suficiente? ¿Qué recursos usa el autor y con qué intención? ¿Quién escribe, a quién y con qué interés? ¿Estoy de acuerdo y por qué? Responder todo permite evaluar sin dejar pasos al azar.",
   "Transferir es usar la lista en un texto distinto: una carta, un discurso o un ensayo breve. Los pasos son los mismos, pero cambian el tono y el medio. Si una respuesta tuya suena débil, revísala: ¿citaste el texto?, ¿diste una razón?, ¿distinguiste hecho de opinión? Mejorar la propia lectura también es parte de aprender."],
  [("evaluar", "juzgar la calidad de un texto con criterios y evidencia"), ("lista de revisión", "serie de preguntas para no olvidar pasos"), ("transferir", "usar lo aprendido en una situación nueva"), ("razonamiento", "cadena de ideas que une la evidencia con la tesis")],
  [("Aplicar la lista a un texto",
    "Carta de ejemplo de un estudiante al director: «Propongo que el acto del lunes sea a la última hora. Ahora lo hacen a las 8:00 y llegan tarde 40 de 300 estudiantes. ¿Qué sentido tiene empezar un acto con tanta gente ausente? Quizás a otra hora asistan todos». Identifica tesis, un hecho, un recurso y el contexto.",
    ["Tesis: el acto debería ser a la última hora.", "Hecho: llegan tarde 40 de 300.", "Recurso: pregunta retórica y oración dubitativa («quizás»).", "Contexto: estudiante a la autoridad, tono formal."],
    "Tesis: acto a la última hora; hecho: 40 de 300 llegan tarde; recurso: pregunta retórica y dubitativa; contexto: estudiante al director"),
   ("Revisar una respuesta débil",
    "Respuesta de un estudiante: «La carta es buena porque me gustó». Mejórala con una razón.",
    ["Falta la razón que se relaciona con el texto.", "Cito el dato: 40 de 300.", "Añado que es pertinente."],
    "«La carta es convincente porque cita un dato pertinente: llegan tarde 40 de 300 estudiantes»")],
  [("Responder cada pregunta de la lista con una sola palabra.", "No se ve el razonamiento.", "Escribe una frase con una cita o dato."),
   ("Saltarse el contexto cuando se hace la evaluación.", "El contexto puede revelar interés o tono.", "Pregunta quién escribe y para quién.")],
  ([E("¿Qué se identifica primero al evaluar un texto argumentativo?", "La tesis", "Sin ella no se puede evaluar la evidencia."),
    E("¿Qué se debe revisar de la evidencia: pertinencia y suficiencia o la longitud?", "Pertinencia y suficiencia", "Son los criterios de la clase."),
    E("¿Qué se hace al final: se declara una postura con razones o se copia el texto?", "Se declara una postura con razones", "Es la lectura propia.")],
   [E("Discurso de ejemplo: «Vecinos: en 30 días, 12 faroles no funcionan. ¿Quién se atrevería a caminar así de noche? Ojalá los reparen pronto». ¿Qué tesis se deduce? A) deben repararse los faroles B) los vecinos no deben salir", "A) deben repararse los faroles", "Se deduce de la queja y del deseo final."),
    E("Discurso de ejemplo: «Vecinos: en 30 días, 12 faroles no funcionan». ¿Qué dato comprobable aparece?", "12 faroles no funcionan en 30 días", "Es una cifra que se puede revisar."),
    E("En un discurso de ejemplo sobre faroles sin luz aparece la frase «¿Quién se atrevería a caminar así de noche?». ¿Qué es? A) pregunta retórica B) pregunta de encuesta", "A) pregunta retórica", "No espera respuesta, sugiere el peligro.")],
   [E("Carta de ejemplo: «Quiero más tiempo para el almuerzo. Creo que 45 minutos son pocos». Evidencia: ninguna. ¿Es suficiente la evidencia? Responde sí o no y por qué.", "No; no trae ningún dato", "Una impresión sin datos no sostiene la tesis."),
    E("Carta de ejemplo del dueño del kiosco que pide cerrar el casino: ¿qué interés puede tener? A) vender más en su kiosco B) mejorar las notas", "A) vender más en su kiosco", "Cerrar el casino lo beneficiaría."),
    E("Ordena los pasos de evaluación: (1) postura propia, (2) tesis, (3) revisar evidencia. Escribe los números en orden.", "2, 3, 1", "Se identifica la tesis, se revisa la evidencia y luego se opina.")],
   [E("Columna de ejemplo: «Los juegos de computador distraen a los jóvenes. Un estudiante que conozco repitió el año». Evalúa: ¿qué falla? A) generaliza a partir de un caso B) cita a un experto", "A) generaliza a partir de un caso", "Un solo conocido no sostiene la afirmación general."),
    E("Una respuesta dice: «El texto usa muchos recursos». ¿Qué le falta para ser una buena evaluación?", "Nombrar los recursos y su intención", "Sin ejemplos y efecto, no se sostiene.")],
   [arith("Carta de ejemplo: «El liceo debe tener una cancha techada. En invierno se suspenden 8 clases de educación física al mes». Si el invierno dura 3 meses, ¿cuántas clases se suspenden en total?", "8 * 3", "Se multiplican las clases suspendidas por mes por los meses."),
    E("En una carta de ejemplo aparece la frase «Tal vez se suspendan 8 clases al mes». ¿Qué tipo de oración es? A) dubitativa B) desiderativa", "A) dubitativa", "«Tal vez» muestra una estimación no segura.")]),
  [E("Texto de ejemplo: «Mi vecino dice que todos los estudiantes del liceo llegan atrasados». Si lo evalúas, ¿qué error ves? A) generalización a partir de un caso B) falta de cierre", "A) generalización a partir de un caso", "Un vecino no representa a todos los estudiantes.")],
  [E("¿Qué es la tesis?", "La idea que se defiende", "Es el eje del texto."),
   E("¿La evidencia debe ser pertinente y suficiente?", "Sí", "Así sostiene la tesis."),
   E("¿Qué se agrega al final de una evaluación?", "La postura propia con razones", "Cierra la lectura crítica.")],
  ("Lee esta columna de ejemplo: «Los estudiantes de 1.º medio deberían dar su opinión en el consejo del liceo. Hoy el consejo tiene 8 adultos y ningún estudiante. ¿Es justo decidir sobre nosotros sin nosotros? Ojalá nos escuchen. Tal vez un representante bastaría». Evalúa el texto con la lista: 1) tesis, 2) un hecho y una opinión, 3) los tres recursos, 4) si la evidencia basta, 5) tu postura con una razón.",
   "1) Los estudiantes deberían participar en el consejo. 2) Hecho: el consejo tiene 8 adultos y ningún estudiante; opinión: «es injusto». 3) Retórica: «¿Es justo…?»; desiderativa: «Ojalá nos escuchen»; dubitativa: «Tal vez un representante bastaría». 4) Hay un dato pertinente, pero falta más evidencia. 5) Estoy de acuerdo en parte porque el dato es pertinente, pero faltan ejemplos.",
   ["identifica los elementos pedidos", "justifica con frases del texto", "declara una postura fundamentada"], ["cinco respuestas numeradas"], ["omitir la justificación"], "Revisa que cada respuesta cite una frase del texto."),
  "Aplica la lista de revisión a un aviso o comentario que veas esta semana.",
  "Escribe una columna de cinco frases con tesis, un dato, una pregunta retórica y un cierre.")
